import { useState, useEffect } from "react";
import { useNavigate, useParams } from "react-router-dom";
import "./styles/AdminP.css";

function AdminP({ processes }) {
  const [showEditModal, setShowEditModal] = useState(false);
  const [editingProcess, setEditingProcess] = useState(null);
  const [processesList, setProcessesList] = useState(processes || []);
  const navigate = useNavigate();
  const { userType } = useParams();  // Obtiene el tipo de usuario de la URL

  // Lógica para editar un proceso
  const handleEditClick = (processData) => {
    setEditingProcess({ ...processData });
    setShowEditModal(true);
  };

  // Cerrar el modal
  const handleCloseModal = () => {
    setShowEditModal(false);
    setEditingProcess(null);
  };

  // Guardar cambios en un proceso
  const handleSaveProcess = (e) => {
    e.preventDefault();
    setProcessesList(
      processesList.map((p) =>
        p.id === editingProcess.id ? editingProcess : p
      )
    );
    handleCloseModal();
  };

  // Eliminar un proceso
  const handleDeleteProcess = (id) => {
    setProcessesList(processesList.filter((p) => p.id !== id));
  };

  // Agregar un nuevo proceso
  const handleAddProcess = () => {
    const newProcess = {
      id: processesList.length + 1,
      name: "",
      description: "",
      requirements: "",
      time: "",
    };
    setEditingProcess(newProcess);
    setShowEditModal(true);
  };

  // Volver a la página anterior
  const handleBack = () => {
    navigate(-1); // Regresa a la página anterior
  };

  useEffect(() => {
    // Si se necesita realizar alguna lógica cuando cambia el tipo de usuario
  }, [userType]);

  return (
    <div className="adminP-container">
      <header className="adminP-header">
        <div className="adminP-header-left">
          {/* Mostrar el botón de regresar solo si es "super" */}
          {userType === "super" && (
            <button className="adminP-back-btn" onClick={handleBack} title="Volver">
              <i className="bi bi-chevron-double-left"></i>
            </button>
          )}
          <h1 className="adminP-title">TalkinPon</h1>
        </div>

        {/* Icono de usuario cambia si es "super" o no */}
        <div className="adminP-user-icon-container">
          {userType === "super" ? (
            <i className="bi bi-person-circle user-icon"></i>
          ) : (
            <button className="adminP-user-btn">Usuario</button> // Cambia a botón
          )}
          <h5>{userType === "super" ? "Super Administrador" : "Administrador"}</h5>
        </div>
      </header>

      <main className="adminP-main">
        <div className="adminP-section">
          <h2 className="adminP-section-header">Gestión de Procesos</h2>

          <table className="adminP-table">
            <thead>
              <tr>
                <th>Nombre del proceso</th>
                <th>Descripción</th>
                <th>Requisitos</th>
                <th>Dependencia</th>
                <th>Opciones</th>
              </tr>
            </thead>
            <tbody>
              {processesList.map((p) => (
                <tr key={p.id}>
                  <td>{p.name}</td>
                  <td>{p.description}</td>
                  <td>{p.requirements}</td>
                  <td>{p.time}</td>
                  <td>
                    <button
                      className="adminP-option-btn edit"
                      onClick={() => handleEditClick(p)}
                      title="Editar"
                    >
                      <i className="bi bi-pencil-fill"></i>
                    </button>
                    <button
                      className="adminP-option-btn delete"
                      onClick={() => handleDeleteProcess(p.id)}
                      title="Eliminar"
                    >
                      <i className="bi bi-trash-fill"></i>
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>

          <div className="adminP-add-user-container">
            <button className="adminP-add-user-btn" onClick={handleAddProcess}>
              Agregar nuevo proceso
            </button>
          </div>
        </div>
      </main>

      {/* Modal para editar o agregar un proceso */}
      {showEditModal && editingProcess && (
        <div className="adminP-modal-overlay" onClick={handleCloseModal}>
          <div
            className="adminP-modal-content"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="adminP-modal-header">
              <h2>
                {editingProcess.name ? "Editar Proceso" : "Agregar Proceso"}
              </h2>
              <button className="adminP-modal-close" onClick={handleCloseModal}>
                ✕
              </button>
            </div>
            <form className="adminP-edit-form" onSubmit={handleSaveProcess}>
              <div className="adminP-form-group">
                <label>Nombre:</label>
                <input
                  type="text"
                  value={editingProcess.name}
                  onChange={(e) =>
                    setEditingProcess({ ...editingProcess, name: e.target.value })
                  }
                  placeholder="Nombre del proceso"
                  required
                />
              </div>
              <div className="adminP-form-group">
                <label>Descripción:</label>
                <input
                  type="text"
                  value={editingProcess.description}
                  onChange={(e) =>
                    setEditingProcess({ ...editingProcess, description: e.target.value })
                  }
                  placeholder="Descripción del proceso"
                  required
                />
              </div>
              <div className="adminP-form-group">
                <label>Requisitos:</label>
                <input
                  type="text"
                  value={editingProcess.requirements}
                  onChange={(e) =>
                    setEditingProcess({ ...editingProcess, requirements: e.target.value })
                  }
                  placeholder="Requisitos"
                  required
                />
              </div>
              <div className="adminP-form-group">
                <label>Tiempo estimado:</label>
                <input
                  type="text"
                  value={editingProcess.time}
                  onChange={(e) =>
                    setEditingProcess({ ...editingProcess, time: e.target.value })
                  }
                  placeholder="Tiempo estimado"
                  required
                />
              </div>
              <div className="adminP-form-actions">
                <button
                  type="button"
                  className="adminP-btn-cancel"
                  onClick={handleCloseModal}
                >
                  Cancelar
                </button>
                <button type="submit" className="adminP-btn-save">
                  Guardar
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

export default AdminP;
